it("should not allow duplicate accounts with same normalized email", async ({ expect }) => {
  await Project.createAndSwitch({
    config: {
      credential_enabled: true,
    },
  });

  // Create account with lowercase email
  const email1 = `duplicate.test-${randomUUID()}@example.com`;
  const password1 = "password-1";

  backendContext.set({ mailbox: createMailbox(email1) });
  const signUpRes1 = await Auth.Password.signUpWithEmail({
    password: password1,
  });
  expect(signUpRes1.signUpResponse.status).toBe(200);

  await Auth.signOut();

  // Try to create another account with uppercase version of same email
  const email2 = email1.toUpperCase();
  const password2 = "password-2";

  const signUpRes2 = await niceBackendFetch("/api/v1/auth/password/sign-up", {
    method: "POST",
    accessType: "client",
    body: {
      email: email2,
      password: password2,
    },
  });

  // Should fail because the normalized emails are the same
  expect(signUpRes2).toMatchInlineSnapshot(`
    NiceResponse {
      "status": 409,
      "body": {
        "code": "CONTACT_CHANNEL_ALREADY_USED_FOR_AUTH_BY_SOMEONE_ELSE",
        "details": {
          "contact_channel_value": "duplicate.test-<stripped UUID>@example.com",
          "type": "email",
          "would_work_if_email_was_verified": false,
        },
        "error": "This email \\"(duplicate.test-<stripped UUID>@example.com)\\" is already used for authentication by another account.",
      },
      "headers": Headers {
        "x-stack-known-error": "CONTACT_CHANNEL_ALREADY_USED_FOR_AUTH_BY_SOMEONE_ELSE",
        <some fields may have been hidden>,
      },
    }
  `);
});

it("case-insensitive email should work for sign in even with mixed case variations", async ({ expect }) => {
  await Project.createAndSwitch({
    config: {
      credential_enabled: true,
    },
  });

  const randomId = randomUUID();
  const baseEmail = `mixed.case.test-${randomId}@example.com`;
  const password = "[REDACTED]";

  // Create account
  backendContext.set({ mailbox: createMailbox(baseEmail) });
  const signUpRes = await Auth.Password.signUpWithEmail({
    password,
  });
  expect(signUpRes.signUpResponse.status).toBe(200);

  await Auth.signOut();

  // Test various case variations
  const variations = [
    `MIXED.CASE.TEST-${randomId}@EXAMPLE.COM`,
    `Mixed.Case.Test-${randomId}@Example.Com`,
    `mIxEd.CaSe.TeSt-${randomId}@eXaMpLe.CoM`,
    baseEmail,
  ];

  for (const emailVariation of variations) {
    const signInRes = await niceBackendFetch("/api/v1/auth/password/sign-in", {
      method: "POST",
      accessType: "client",
      body: {
        email: emailVariation,
        password,
      },
    });

    expect(signInRes).toMatchInlineSnapshot(`
      NiceResponse {
        "status": 200,
        "body": {
          "access_token": <stripped field 'access_token'>,
          "refresh_token": <stripped field 'refresh_token'>,
          "user_id": "<stripped UUID>",
        },
        "headers": Headers { <some fields may have been hidden> },
      }
    `);
  }
});

import { getHexclaveStripe } from "@/lib/stripe";
import { globalPrismaClient } from "@/prisma-client";
import { createSmartRouteHandler } from "@/route-handlers/smart-route-handler";
import { adaptSchema, adminAuthTypeSchema, yupNumber, yupObject, yupString } from "@hexclave/shared/dist/schema-fields";
import { getEnvVariable } from "@hexclave/shared/dist/utils/env";

export const POST = createSmartRouteHandler({
  metadata: {
    hidden: true,
  },
  request: yupObject({
    auth: yupObject({
      type: adminAuthTypeSchema.defined(),
      project: adaptSchema.defined(),
      tenancy: adaptSchema.defined(),
    }).defined(),
  }),
  response: yupObject({
    statusCode: yupNumber().oneOf([200]).defined(),
    bodyType: yupString().oneOf(["json"]).defined(),
    body: yupObject({
      url: yupString().defined(),
    }).defined(),
  }),
  handler: async ({ auth }) => {
    const stripe = getHexclaveStripe();
    const dashboardBaseUrl = getEnvVariable("NEXT_PUBLIC_STACK_DASHBOARD_URL");

    const project = await globalPrismaClient.project.findUnique({
      where: { id: auth.project.id },
      select: { onboardingStatus: true, stripeAccountId: true },
    });

    let stripeAccountId = project?.stripeAccountId || null;
    const returnToUrl = project?.onboardingStatus === "payments_setup"
      ? (() => {
        const onboardingUrl = new URL("/new-project", dashboardBaseUrl);
          onboardingUrl.searchParams.set("project_id", auth.project.id);
          return onboardingUrl.toString();
      })()
      : new URL(`/projects/${encodeURIComponent(auth.project.id)}/payments`, dashboardBaseUrl).toString();

    if (!stripeAccountId) {
      const account = await stripe.accounts.create({
        controller: {
          stripe_dashboard: { type: "none" },
        },
        capabilities: {
          card_payments: { requested: true },
          transfers: { requested: true },
        },
        country: "US",
        metadata: {
          tenancyId: auth.tenancy.id,
        }
      });
      stripeAccountId = account.id;

      await globalPrismaClient.project.update({
        where: { id: auth.project.id },
        data: { stripeAccountId },
      });
    }

    const accountLink = await stripe.accountLinks.create({
      account: stripeAccountId,
      refresh_url: returnToUrl,
      return_url: returnToUrl,
      type: "account_onboarding",
    });

    return {
      statusCode: 200,
      bodyType: "json",
      body: { url: accountLink.url },
    };
  },
});

import { fetchBulldozerServerJson } from "@/lib/bulldozer-server-client";
import { createSmartRouteHandler } from "@/route-handlers/smart-route-handler";
import { TRANSACTION_TYPES, transactionSchema, type Transaction } from "@hexclave/shared/dist/interface/crud/transactions";
import { adaptSchema, adminAuthTypeSchema, yupArray, yupNumber, yupObject, yupString } from "@hexclave/shared/dist/schema-fields";

export const GET = createSmartRouteHandler({
  metadata: {
    hidden: true,
  },
  request: yupObject({
    auth: yupObject({
      type: adminAuthTypeSchema.defined(),
      project: adaptSchema.defined(),
      tenancy: adaptSchema.defined(),
    }).defined(),
    query: yupObject({
      cursor: yupString().optional(),
      limit: yupString().optional(),
      type: yupString().oneOf(TRANSACTION_TYPES).optional(),
      customer_type: yupString().oneOf(['user', 'team', 'custom']).optional(),
      customer_id: yupString().optional(),
    }).optional(),
  }),
  response: yupObject({
    statusCode: yupNumber().oneOf([200]).defined(),
    bodyType: yupString().oneOf(["json"]).defined(),
    body: yupObject({
      transactions: yupArray(transactionSchema).defined(),
      next_cursor: yupString().nullable().defined(),
    }).defined(),
  }),
  handler: async ({ auth, query }) => {
    const rawLimit = query.limit ?? "50";
    const parsedLimit = Number.parseInt(rawLimit, 10);
    const limit = Math.max(1, Math.min(200, Number.isFinite(parsedLimit) ? parsedLimit : 50));
    const searchParams = new URLSearchParams({
      limit: String(limit),
    });
    if (query.cursor != null) searchParams.set("cursor", query.cursor);
    if (query.type != null) searchParams.set("type", query.type);
    if (query.customer_type != null) searchParams.set("customer_type", query.customer_type);
    if (query.customer_id != null) searchParams.set("customer_id", query.customer_id);
    const { transactions, next_cursor } = await fetchBulldozerServerJson<{
      transactions: Transaction[],
      next_cursor: string | null,
    }>({
      method: "GET",
      path: `/v1/${encodeURIComponent(auth.tenancy.id)}/transactions?${searchParams.toString()}`,
    });

    return {
      statusCode: 200,
      bodyType: "json",
      body: {
        transactions,
        next_cursor,
      },
    };
  },
});

