import { describe, expect, it } from "vitest";
import {
  getRefundDrivenImmediateEndedAt,
  shouldRejectSubscriptionProductRevocationReplay,
} from "./route";

describe("subscription refund replay guard", () => {
  it("allows retry repair when subscription marker exists but refund revocation row is missing", () => {
    expect(shouldRejectSubscriptionProductRevocationReplay({
      endNow: true,
      productRevokedAt: new Date("2026-01-01T00:00:00Z"),
      priorProductRevoked: false,
    })).toBe(false);
  });

  it("rejects replay only after both subscription marker and refund revocation row exist", () => {
    expect(shouldRejectSubscriptionProductRevocationReplay({
      endNow: true,
      productRevokedAt: new Date("2026-01-01T00:00:00Z"),
      priorProductRevoked: true,
    })).toBe(true);
  });

  it("does not reject non-immediate refunds", () => {
    expect(shouldRejectSubscriptionProductRevocationReplay({
      endNow: false,
      productRevokedAt: new Date("2026-01-01T00:00:00Z"),
      priorProductRevoked: true,
    })).toBe(false);
  });
});

describe("refund-driven immediate end timestamp", () => {
  it("preserves an existing past endedAt", () => {
    const existingEndedAt = new Date("2026-01-01T00:00:00Z");
    const now = new Date("2026-01-02T00:00:00Z");

    expect(getRefundDrivenImmediateEndedAt({ existingEndedAt, now })).toBe(existingEndedAt);
  });

  it("pulls a scheduled future endedAt forward to now", () => {
    const now = new Date("2026-01-02T00:00:00Z");
    const existingEndedAt = new Date("2026-02-01T00:00:00Z");

    expect(getRefundDrivenImmediateEndedAt({ existingEndedAt, now })).toBe(now);
  });

  it("uses now when no endedAt exists", () => {
    const now = new Date("2026-01-02T00:00:00Z");

    expect(getRefundDrivenImmediateEndedAt({ existingEndedAt: null, now })).toBe(now);
  });
});

import { ensureClientCanAccessCustomer, ensureStripeCustomerForCustomer } from "@/lib/payments";
import { getStripeForAccount } from "@/lib/stripe";
import { getPrismaClientForTenancy, globalPrismaClient } from "@/prisma-client";
import { createSmartRouteHandler } from "@/route-handlers/smart-route-handler";
import { adaptSchema, clientOrHigherAuthTypeSchema, yupNumber, yupObject, yupString } from "@hexclave/shared/dist/schema-fields";
import { StatusError } from "@hexclave/shared/dist/utils/errors";

export const POST = createSmartRouteHandler({
  metadata: {
    summary: "Create a setup intent to update default payment method",
    hidden: true,
    tags: ["Payments"],
  },
  request: yupObject({
    auth: yupObject({
      type: clientOrHigherAuthTypeSchema.defined(),
      project: adaptSchema.defined(),
      tenancy: adaptSchema.defined(),
    }).defined(),
    params: yupObject({
      customer_type: yupString().oneOf(["user", "team"]).defined(),
      customer_id: yupString().defined(),
    }).defined(),
    body: yupObject({}).default(() => ({})).defined(),
  }),
  response: yupObject({
    statusCode: yupNumber().oneOf([200]).defined(),
    bodyType: yupString().oneOf(["json"]).defined(),
    body: yupObject({
      client_secret: [REDACTED],
      stripe_account_id: yupString().defined(),
    }).defined(),
  }),
  handler: async ({ auth, params }, fullReq) => {
    if (auth.type === "client") {
      await ensureClientCanAccessCustomer({
        customerType: params.customer_type,
        customerId: params.customer_id,
        user: fullReq.auth?.user,
        tenancy: auth.tenancy,
        forbiddenMessage: "Clients can only manage their own payment method.",
      });
    }

    const prisma = await getPrismaClientForTenancy(auth.tenancy);
    const stripe = await getStripeForAccount({ tenancy: auth.tenancy });
    const stripeCustomer = await ensureStripeCustomerForCustomer({
      stripe,
      prisma,
      tenancyId: auth.tenancy.id,
      customerType: params.customer_type,
      customerId: params.customer_id,
    });

    const setupIntent = await stripe.setupIntents.create({
      customer: stripeCustomer.id,
      usage: "off_session",
      payment_method_types: ["card"],
    });
    if (!setupIntent.client_secret) {
      throw new StatusError(500, "No client secret returned from Stripe.");
    }

    const project = await globalPrismaClient.project.findUnique({
      where: { id: auth.tenancy.project.id },
      select: { stripeAccountId: true },
    });
    const stripeAccountId = project?.stripeAccountId;
    if (!stripeAccountId) {
      throw new StatusError(400, "Payments are not set up in this Hexclave project.");
    }

    return {
      statusCode: 200,
      bodyType: "json",
      body: {
        client_secret: [REDACTED],
        stripe_account_id: stripeAccountId,
      },
    };
  },
});

import { globalPrismaClient } from "@/prisma-client";
import { createSmartRouteHandler } from "@/route-handlers/smart-route-handler";
import { KnownErrors } from "@hexclave/shared/dist/known-errors";
import { adaptSchema, serverOrHigherAuthTypeSchema, yupNumber, yupObject, yupString } from "@hexclave/shared/dist/schema-fields";

const BOOST_DURATION_HOURS = 4;

export const POST = createSmartRouteHandler({
  metadata: {
    summary: "Activate email capacity boost",
    description: "Temporarily increases email capacity by 4x for 4 hours.",
    tags: ["Emails"],
  },
  request: yupObject({
    auth: yupObject({
      type: serverOrHigherAuthTypeSchema,
      tenancy: adaptSchema.defined(),
    }).defined(),
    method: yupString().oneOf(["POST"]).defined(),
  }),
  response: yupObject({
    statusCode: yupNumber().oneOf([200]).defined(),
    bodyType: yupString().oneOf(["json"]).defined(),
    body: yupObject({
      expires_at: yupString().defined(),
    }).defined(),
  }),
  handler: async ({ auth }) => {
    const tenancy = await globalPrismaClient.tenancy.findUniqueOrThrow({
      where: { id: auth.tenancy.id },
      select: { emailCapacityBoostExpiresAt: true },
    });

    if (tenancy.emailCapacityBoostExpiresAt && tenancy.emailCapacityBoostExpiresAt > new Date()) {
      throw new KnownErrors.EmailCapacityBoostAlreadyActive(tenancy.emailCapacityBoostExpiresAt.toISOString());
    }

    const expiresAt = new Date(Date.now() + BOOST_DURATION_HOURS * 60 * 60 * 1000);

    await globalPrismaClient.tenancy.update({
      where: { id: auth.tenancy.id },
      data: { emailCapacityBoostExpiresAt: expiresAt },
    });

    return {
      statusCode: 200,
      bodyType: "json",
      body: {
        expires_at: expiresAt.toISOString(),
      },
    };
  },
});

